"""Build an object store from everything intact in the repo: loose objects, both packs, resolving deltas."""
import os, struct, zlib, hashlib, binascii, sys, json
REPO = '/app/repo.git'
TYPES = {1:'commit',2:'tree',3:'blob',4:'tag'}

def parse_idx(path):
    idx = open(path,'rb').read()
    assert idx[:4] == b'\xfftOc'
    fanout = struct.unpack('>256I', idx[8:8+1024]); n = fanout[255]
    pos = 8+1024
    shas = [idx[pos+20*i:pos+20*i+20].hex() for i in range(n)]; pos += 20*n
    crcs = struct.unpack('>%dI'%n, idx[pos:pos+4*n]); pos += 4*n
    offs = struct.unpack('>%dI'%n, idx[pos:pos+4*n]); pos += 4*n
    return sorted(zip(offs, shas, crcs))

def parse_entry_header(pack, off):
    p = off
    b = pack[p]; p += 1
    t = (b>>4)&7; size = b&15; shift = 4
    while b & 0x80:
        b = pack[p]; p += 1
        size |= (b&0x7f)<<shift; shift += 7
    base = None
    if t == 6:
        b = pack[p]; p += 1; o = b&0x7f
        while b & 0x80:
            b = pack[p]; p += 1; o = ((o+1)<<7)|(b&0x7f)
        base = ('ofs', off - o)
    elif t == 7:
        base = ('ref', pack[p:p+20].hex()); p += 20
    return t, size, base, p

def inflate_exact(buf):
    d = zlib.decompressobj()
    out = d.decompress(buf)
    return out, len(buf) - len(d.unused_data)

def varint(data, p):
    v = 0; shift = 0
    while True:
        b = data[p]; p += 1
        v |= (b&0x7f)<<shift; shift += 7
        if not b & 0x80: break
    return v, p

def parse_delta(delta):
    """Return (base_size, result_size, ops) where ops are ('copy', off, len) or ('insert', bytes)."""
    bs, p = varint(delta, 0)
    rs, p = varint(delta, p)
    ops = []
    while p < len(delta):
        c = delta[p]; p += 1
        if c & 0x80:
            off = 0; ln = 0
            if c & 0x01: off |= delta[p]; p += 1
            if c & 0x02: off |= delta[p] << 8; p += 1
            if c & 0x04: off |= delta[p] << 16; p += 1
            if c & 0x08: off |= delta[p] << 24; p += 1
            if c & 0x10: ln |= delta[p]; p += 1
            if c & 0x20: ln |= delta[p] << 8; p += 1
            if c & 0x40: ln |= delta[p] << 16; p += 1
            if ln == 0: ln = 0x10000
            ops.append(('copy', off, ln))
        elif c:
            ops.append(('insert', delta[p:p+c])); p += c
        else:
            raise ValueError('bad delta op 0')
    return bs, rs, ops

def apply_delta(base, delta):
    bs, rs, ops = parse_delta(delta)
    assert bs == len(base), (bs, len(base))
    out = bytearray()
    for op in ops:
        if op[0] == 'copy': out += base[op[1]:op[1]+op[2]]
        else: out += op[1]
    assert len(out) == rs
    return bytes(out)

def obj_sha(t, data):
    return hashlib.sha1(b'%s %d\0' % (t.encode(), len(data)) + data).hexdigest()

class Store:
    def __init__(self):
        self.objs = {}      # sha -> (type, data)
        self.sources = {}   # sha -> list of sources
        self.deltas = []    # (sha, pack, off, base, deltadata, type_of_entry)
        self.zeroed = []    # (sha, pack, off, t, size, base)
        self.badloose = []
    def add(self, sha, t, data, src):
        h = obj_sha(t, data)
        if h != sha:
            print('SHA MISMATCH', sha, h, src); return False
        if sha not in self.objs:
            self.objs[sha] = (t, data)
        self.sources.setdefault(sha, []).append(src)
        return True

def load_loose(st):
    od = os.path.join(REPO, 'objects')
    for d in sorted(os.listdir(od)):
        if len(d) != 2: continue
        for f in sorted(os.listdir(os.path.join(od, d))):
            sha = d + f
            raw = open(os.path.join(od, d, f), 'rb').read()
            try:
                out = zlib.decompress(raw)
            except Exception as e:
                st.badloose.append(sha); continue
            hdr, _, data = out.partition(b'\0')
            t, sz = hdr.decode().split()
            assert int(sz) == len(data)
            st.add(sha, t, data, 'loose')

def load_pack(st, packpath, idxpath, tag):
    pack = open(packpath, 'rb').read()
    entries = parse_idx(idxpath)
    off2sha = {off: sha for off, sha, crc in entries}
    for i, (off, sha, crc) in enumerate(entries):
        end = entries[i+1][0] if i+1 < len(entries) else len(pack)-20
        ok = (binascii.crc32(pack[off:end]) & 0xffffffff) == crc
        t, size, base, p = parse_entry_header(pack, off)
        if not ok:
            st.zeroed.append((sha, tag, off, t, size, base, end-off))
            continue
        data, used = inflate_exact(pack[p:end])
        assert len(data) == size, (sha, len(data), size)
        if t in (1,2,3,4):
            st.add(sha, TYPES[t], data, tag)
        else:
            if base[0] == 'ofs':
                b = ('sha', off2sha[base[1]])
            else:
                b = ('sha', base[1])
            st.deltas.append((sha, tag, off, b[1], data))
    return off2sha

def resolve(st):
    progress = True
    while progress:
        progress = False
        rest = []
        for d in st.deltas:
            sha, tag, off, bsha, delta = d
            if sha in st.objs:
                continue
            if bsha in st.objs:
                bt, bdata = st.objs[bsha]
                out = apply_delta(bdata, delta)
                if st.add(sha, bt, out, tag + ':delta'):
                    progress = True
            else:
                rest.append(d)
        st.deltas = rest

def build():
    st = Store()
    load_loose(st)
    load_pack(st, REPO+'/objects/pack/pack-0edbe236157d7f40502eaa2e054bc68160f770ab.pack', REPO+'/objects/pack/pack-0edbe236157d7f40502eaa2e054bc68160f770ab.idx', 'p0edbe')
    load_pack(st, '/tmp/work/orphan/pack-dc1a3d5e56cdb2c83174659a7deaaca10d01e520.pack', '/tmp/work/orphan/pack-dc1a3d5e56cdb2c83174659a7deaaca10d01e520.idx', 'pdc1a')
    resolve(st)
    return st

def parse_tree(data):
    ents = []; p = 0
    while p < len(data):
        sp = data.index(b' ', p); nul = data.index(b'\0', sp)
        mode = data[p:sp].decode(); name = data[sp+1:nul]
        sha = data[nul+1:nul+21].hex(); p = nul+21
        ents.append((mode, name, sha))
    return ents

def refs_of(t, data):
    if t == 'tree':
        return [e[2] for e in parse_tree(data)]
    if t == 'commit':
        out = []
        for line in data.split(b'\n'):
            if line == b'': break
            if line.startswith(b'tree ') or line.startswith(b'parent '):
                out.append(line.split()[1].decode())
        return out
    if t == 'tag':
        for line in data.split(b'\n'):
            if line.startswith(b'object '): return [line.split()[1].decode()]
    return []

def roots():
    rs = set()
    for dp, dn, fn in os.walk(REPO+'/refs'):
        for f in fn:
            rs.add(open(os.path.join(dp,f)).read().strip())
    for line in open(REPO+'/packed-refs'):
        if line.startswith('#'): continue
        if line.startswith('^'): rs.add(line[1:].strip()); continue
        rs.add(line.split()[0])
    for dp, dn, fn in os.walk(REPO+'/logs'):
        for f in fn:
            for line in open(os.path.join(dp,f)):
                a, b = line.split()[:2]
                for x in (a,b):
                    if x != '0'*40: rs.add(x)
    return rs

def closure(st, start):
    seen = set(); missing = {}; stack = list(start)
    while stack:
        s = stack.pop()
        if s in seen: continue
        seen.add(s)
        if s not in st.objs:
            missing.setdefault(s, set()); continue
        t, data = st.objs[s]
        for r in refs_of(t, data):
            if r not in st.objs:
                missing.setdefault(r, set()).add((t, s))
            stack.append(r)
    return seen, missing

if __name__ == '__main__':
    st = build()
    print('objects in store:', len(st.objs))
    print('bad loose:', st.badloose)
    print('unresolved deltas:', [(d[0], d[1], d[2], d[3], len(d[4])) for d in st.deltas])
    print('zeroed entries:')
    for z in st.zeroed: print('  ', z)
    seen, missing = closure(st, roots())
    print('reachable (incl missing):', len(seen))
    print('MISSING reachable objects:')
    for m, refs in sorted(missing.items()):
        print('  ', m, 'referenced by', sorted(refs))
    # unreachable objects in store
    unreach = [s for s in st.objs if s not in seen]
    print('unreachable objects in store:', len(unreach))
    from collections import Counter
    print(Counter(st.objs[s][0] for s in unreach))
