import sys, json; sys.path.insert(0, '/tmp/work/scripts')
from store import *
st = build()
def walk(tree_sha, prefix, out, missing_trees):
    if tree_sha not in st.objs:
        missing_trees.append((prefix, tree_sha)); return
    t, d = st.objs[tree_sha]
    for m, n, h in parse_tree(d):
        p = prefix + n.decode()
        if m == '40000':
            walk(h, p + '/', out, missing_trees)
        else:
            out[p] = (m, h)
commit_paths = {}
for s,(t,d) in st.objs.items():
    if t != 'commit': continue
    tree = d.split(b'\n')[0].split()[1].decode()
    out = {}; mt = []
    walk(tree, '', out, mt)
    commit_paths[s] = {'tree': tree, 'paths': out, 'missing_trees': mt}
json.dump(commit_paths, open('/tmp/work/commit_paths.json','w'))
# all distinct paths
allpaths = sorted(set(p for c in commit_paths.values() for p in c['paths']))
print('ALL PATHS EVER:'); print('\n'.join(allpaths))
EOF
